function LabeledFlow({ spec }: { spec: FlowSpec }) {
  const n = spec.steps.length;
  const gap = 22;
  const total = 680;
  const w = (total - gap * (n - 1)) / n;
  const y = 180;
  const h = 76;
  return (
    <Canvas>
      {spec.steps.map((label, i) => {
        const x = 60 + i * (w + gap);
        const hot = i === spec.highlight;
        const first = i === 0;
        const lines = label.split("|");
        return (
          <g key={label}>
            <rect x={x} y={y} width={w} height={h} rx="10" fill={first ? INK : "#ffffff"} stroke={hot ? ORANGE : INK} strokeWidth={hot ? 2.4 : 1.6} strokeOpacity={hot || first ? 1 : 0.45} />
            {lines.map((ln, j) => (
              <text key={j} x={x + w / 2} y={y + h / 2 + 5 + (j - (lines.length - 1) / 2) * 16} textAnchor="middle" fontFamily="monospace" fontSize="12" fill={first ? "#faf9f6" : hot ? ORANGE : INK}>
                {ln}
              </text>
            ))}
            {i < n - 1 && (
              <g>
                <line x1={x + w} y1={y + h / 2} x2={x + w + gap} y2={y + h / 2} stroke={LINE} strokeWidth="2" />
                <path d={`M${x + w + gap - 7},${y + h / 2 - 5} L${x + w + gap},${y + h / 2} L${x + w + gap - 7},${y + h / 2 + 5}`} stroke={LINE} strokeWidth="2" fill="none" />
              </g>
            )}
          </g>
        );
      })}
      {spec.loop && (
        <g>
          <path d={`M${60 + total - w / 2},${y + h + 6} C${60 + total - w / 2},${y + h + 80} ${60 + w / 2},${y + h + 80} ${60 + w / 2},${y + h + 6}`} stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
          <text x="400" y={y + h + 92} textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>{spec.loop}</text>
        </g>
      )}
      {spec.branch && (
        <g>
          <line x1={60 + spec.branch.from * (w + gap) + w / 2} y1={y + h} x2={60 + spec.branch.from * (w + gap) + w / 2} y2={y + h + 50} stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" />
          <text x={60 + spec.branch.from * (w + gap) + w / 2} y={y + h + 70} textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>{spec.branch.label}</text>
        </g>
      )}
    </Canvas>
  );
}

/* ------------------------------------------------------------------
 * Labeled wireframe diagrams: interface anatomy drawn as grey blocks
 * with the parts named in place, so the banner explains the pattern.
 * ------------------------------------------------------------------ */

type BlockTone = "ink" | "soft" | "white" | "ghost" | "text";

type Block = {
  x: number;
  y: number;
  w: number;
  h: number;
  label?: string;
  tone?: BlockTone;
  hot?: boolean;
  blue?: boolean;
  size?: number;
  left?: boolean;
};

type Note = { x: number; y: number; text: string; anchor?: "start" | "middle" | "end"; color?: "blue" | "orange" | "ink" };

type AnatomySpec = {
  frames?: { x: number; y: number; w: number; h: number; kind: "browser" | "phone" }[];
  blocks: Block[];
  notes?: Note[];
  paths?: { d: string; dashed?: boolean; blue?: boolean }[];
};

const TONE_FILL: Record<BlockTone, string> = { ink: INK, soft: "#f3f2ee", white: "#ffffff", ghost: "none", text: "none" };
const NOTE_FILL = { blue: BLUE, orange: ORANGE, ink: INK };

function BlockShape({ b }: { b: Block }) {
  const tone = b.tone ?? "white";
  const size = b.size ?? 11;
  const lines = b.label ? b.label.split("|") : [];
  const stroke = b.hot ? ORANGE : b.blue ? BLUE : INK;
  const text = tone === "ink" ? "#faf9f6" : b.hot ? ORANGE : b.blue ? BLUE : INK;
  const lineH = size * 1.4;
  return (
    <g>
      <rect
        x={b.x}
        y={b.y}
        width={b.w}
        height={b.h}
        rx={Math.min(8, b.h / 2)}
        fill={TONE_FILL[tone]}
        stroke={tone === "ink" || (tone === "text" && !b.hot) ? "none" : stroke}
        strokeWidth={b.hot || b.blue ? 2 : 1.4}
        strokeOpacity={b.hot || b.blue ? 1 : tone === "soft" ? 0 : 0.35}
        strokeDasharray={tone === "ghost" ? "4 4" : undefined}
      />
      {lines.map((ln, j) => (
        <text
          key={j}
          x={b.left ? b.x + 10 : b.x + b.w / 2}
          y={b.y + b.h / 2 + size * 0.36 + (j - (lines.length - 1) / 2) * lineH}
          textAnchor={b.left ? "start" : "middle"}
          fontFamily="monospace"
          fontSize={size}
          fill={text}
        >
          {ln}
        </text>
      ))}
    </g>
  );
}

function Frame({ f }: { f: NonNullable<AnatomySpec["frames"]>[number] }) {
  if (f.kind === "phone") {
    return (
      <g>
        <rect x={f.x} y={f.y} width={f.w} height={f.h} rx="18" fill="#ffffff" stroke={INK} strokeWidth="2" />
        <rect x={f.x + f.w / 2 - 16} y={f.y + 7} width="32" height="5" rx="2.5" fill={INK} opacity="0.8" />
      </g>
    );
  }
  return (
    <g>
      <rect x={f.x} y={f.y} width={f.w} height={f.h} rx="10" fill="#ffffff" stroke={INK} strokeWidth="2" />
      <line x1={f.x} y1={f.y + 22} x2={f.x + f.w} y2={f.y + 22} stroke={LINE} strokeWidth="1.5" />
      {[0, 1, 2].map((i) => (
        <circle key={i} cx={f.x + 14 + i * 12} cy={f.y + 11} r="3.2" fill={LINE} />
      ))}
    </g>
  );
}

function Anatomy({ spec }: { spec: AnatomySpec }) {
  return (
    <Canvas>
      {spec.frames?.map((f, i) => <Frame key={i} f={f} />)}
      {spec.paths?.map((p, i) => (
        <path key={i} d={p.d} fill="none" stroke={p.blue ? BLUE : LINE} strokeWidth="1.8" strokeDasharray={p.dashed ? "5 5" : undefined} />
      ))}
      {spec.blocks.map((b, i) => (
        <BlockShape key={i} b={b} />
      ))}
      {spec.notes?.map((n, i) => (
        <text key={i} x={n.x} y={n.y} textAnchor={n.anchor ?? "start"} fontFamily="monospace" fontSize="11" fill={NOTE_FILL[n.color ?? "blue"]}>
          {n.text}
        </text>
      ))}
    </Canvas>
  );
}

const arrow = (x: number, y: number, dir: "r" | "d" | "u" | "l") =>
  dir === "r"
    ? `M${x - 7},${y - 5} L${x},${y} L${x - 7},${y + 5}`
    : dir === "l"
      ? `M${x + 7},${y - 5} L${x},${y} L${x + 7},${y + 5}`
      : dir === "d"
        ? `M${x - 5},${y - 7} L${x},${y} L${x + 5},${y - 7}`
        : `M${x - 5},${y + 7} L${x},${y} L${x + 5},${y + 7}`;

/**
 * Column diagram: a heading per column and a short list under each.
 * Used for "what lives where" banners (Shopify stacks, SEO pillars).
 */
function columnsSpec(
  headers: string[],
  items: string[][],
  opts: { top?: string; hotCol?: number; hotItem?: [number, number]; note?: string } = {}
): AnatomySpec {
  const n = headers.length;
  const gap = 16;
  const w = (680 - gap * (n - 1)) / n;
  const hy = opts.top ? 84 : 44;
  const start = hy + 48;
  const most = Math.max(...items.map((c) => c.length));
  const step = Math.min(46, (396 - start) / most);
  const blocks: Block[] = [];
  if (opts.top) blocks.push({ x: 60, y: 36, w: 680, h: 34, label: opts.top, size: 11.5, tone: "ink" });
  headers.forEach((h, i) => {
    const x = 60 + i * (w + gap);
    const hot = i === opts.hotCol;
    blocks.push({ x, y: hy, w, h: 36, label: h, size: 11, tone: hot ? "white" : opts.top ? "soft" : "ink", hot });
    items[i].forEach((label, j) => {
      const isHot = opts.hotItem?.[0] === i && opts.hotItem?.[1] === j;
      blocks.push({ x, y: start + j * step, w, h: step - 8, label, size: 10, hot: isHot, blue: !isHot && hot });
    });
  });
  return { blocks, notes: opts.note ? [{ x: 400, y: 424, text: opts.note, anchor: "middle" }] : undefined };
}

/**
 * Comparison table: a label column and one column per option.
 */
function compareSpec(headers: string[], rows: string[][], opts: { hotCol?: number; note?: string } = {}): AnatomySpec {
  const n = headers.length;
  const x0 = 226;
  const gap = 10;
  const w = (514 - gap * (n - 1)) / n;
  const step = Math.min(52, (400 - 96) / rows.length);
  const blocks: Block[] = [];
  headers.forEach((h, i) =>
    blocks.push({ x: x0 + i * (w + gap), y: 42, w, h: 40, label: h, size: 10.5, tone: i === opts.hotCol ? "white" : "ink", hot: i === opts.hotCol })
  );
  rows.forEach((row, r) => {
    const y = 96 + r * step;
    blocks.push({ x: 60, y, w: 156, h: step - 8, label: row[0], size: 10, tone: "soft", left: true });
    row.slice(1).forEach((cell, c) =>
      blocks.push({ x: x0 + c * (w + gap), y, w, h: step - 8, label: cell, size: 9.5, blue: c === opts.hotCol })
    );
  });
  return { blocks, notes: opts.note ? [{ x: 400, y: 424, text: opts.note, anchor: "middle" }] : undefined };
}

