/* A narrowing ecommerce funnel. Bar widths are illustrative, not data. */
function FunnelBars() {
  const stages = ["Acquisition", "Landing", "Discovery", "Product view", "Add to cart", "Checkout", "Purchase", "Repeat"];
  return (
    <Canvas>
      {stages.map((s, i) => {
        const w = 560 - i * 52;
        const x = 400 - w / 2;
        const y = 48 + i * 44;
        const hot = i === 4;
        return (
          <g key={s}>
            <rect x={x} y={y} width={w} height="34" rx="7" fill={i === 0 ? INK : hot ? "#ffffff" : SOFT} stroke={hot ? ORANGE : "none"} strokeWidth="2.2" />
            <text x="400" y={y + 22} textAnchor="middle" fontFamily="monospace" fontSize="12" fill={i === 0 ? "#faf9f6" : hot ? ORANGE : INK}>
              {s}
            </text>
          </g>
        );
      })}
      <text x="400" y="424" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        measure the rate between each pair of stages, by segment
      </text>
    </Canvas>
  );
}

