/* A checkout user flow with a decision, an alternative path and an error path. */
function UserFlowMap() {
  const nodes = [
    { x: 30, label: ["Product", "page"], ink: true },
    { x: 170, label: ["Cart"] },
    { x: 410, label: ["Delivery"] },
    { x: 540, label: ["Payment"] },
    { x: 670, label: ["Order", "confirmed"], hot: true },
  ];
  const y = 110;
  const h = 56;
  const w = 104;
  return (
    <Canvas>
      {nodes.map((n) => (
        <g key={n.x}>
          <rect x={n.x} y={y} width={w} height={h} rx="10" fill={n.ink ? INK : "#ffffff"} stroke={n.hot ? ORANGE : INK} strokeWidth={n.hot ? 2.4 : 1.6} strokeOpacity={n.ink || n.hot ? 1 : 0.5} />
          {n.label.map((l, j) => (
            <text key={l} x={n.x + w / 2} y={y + h / 2 + 4 + (j - (n.label.length - 1) / 2) * 15} textAnchor="middle" fontFamily="monospace" fontSize="12" fill={n.ink ? "#faf9f6" : n.hot ? ORANGE : INK}>
              {l}
            </text>
          ))}
        </g>
      ))}
      {/* happy path connectors */}
      {[
        [134, 170],
        [274, 302],
        [514, 540],
        [644, 670],
      ].map(([a, b]) => (
        <g key={a}>
          <line x1={a} y1={y + h / 2} x2={b} y2={y + h / 2} stroke={INK} strokeOpacity="0.55" strokeWidth="2" />
          <path d={arrow(b, y + h / 2, "r")} stroke={INK} strokeOpacity="0.55" strokeWidth="2" fill="none" />
        </g>
      ))}
      {/* decision */}
      <path d={`M340,${y - 10} L378,${y + h / 2} L340,${y + h + 10} L302,${y + h / 2} Z`} fill="#ffffff" stroke={BLUE} strokeWidth="2" />
      <text x="340" y={y + h / 2 - 2} textAnchor="middle" fontFamily="monospace" fontSize="10.5" fill={BLUE}>
        Signed
      </text>
      <text x="340" y={y + h / 2 + 11} textAnchor="middle" fontFamily="monospace" fontSize="10.5" fill={BLUE}>
        in?
      </text>
      <line x1="378" y1={y + h / 2} x2="410" y2={y + h / 2} stroke={INK} strokeOpacity="0.55" strokeWidth="2" />
      <path d={arrow(410, y + h / 2, "r")} stroke={INK} strokeOpacity="0.55" strokeWidth="2" fill="none" />
      <text x="394" y={y + h / 2 - 8} textAnchor="middle" fontFamily="monospace" fontSize="10" fill={INK}>
        yes
      </text>
      {/* guest path */}
      <path d={`M340,${y + h + 10} L340,262`} stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
      <text x="352" y="222" fontFamily="monospace" fontSize="10" fill={BLUE}>
        no
      </text>
      <rect x="288" y="262" width="104" height="50" rx="10" fill="#ffffff" stroke={BLUE} strokeWidth="1.8" />
      <text x="340" y="283" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        Guest or
      </text>
      <text x="340" y="298" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        sign in
      </text>
      <path d={`M392,287 L462,287 L462,${y + h + 2}`} stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
      <path d={arrow(462, y + h + 2, "u")} stroke={BLUE} strokeWidth="1.8" fill="none" />
      {/* alternative path from cart */}
      <path d={`M222,${y + h} L222,262`} stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
      <rect x="170" y="262" width="104" height="50" rx="10" fill="#ffffff" stroke={BLUE} strokeWidth="1.8" strokeDasharray="4 4" />
      <text x="222" y="283" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        Save for
      </text>
      <text x="222" y="298" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        later
      </text>
      {/* error path from payment */}
      <path d={`M578,${y + h} L578,262`} stroke={ORANGE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
      <path d={arrow(578, 262, "d")} stroke={ORANGE} strokeWidth="1.8" fill="none" />
      <rect x="520" y="262" width="128" height="62" rx="10" fill="#ffffff" stroke={ORANGE} strokeWidth="1.8" />
      {["Declined:", "keep details,", "offer retry"].map((t, j) => (
        <text key={t} x="584" y={282 + j * 15} textAnchor="middle" fontFamily="monospace" fontSize="11" fill={ORANGE}>
          {t}
        </text>
      ))}
      <path d={`M610,262 L610,${y + h + 2}`} stroke={ORANGE} strokeWidth="1.8" strokeDasharray="5 5" fill="none" />
      <path d={arrow(610, y + h + 2, "u")} stroke={ORANGE} strokeWidth="1.8" fill="none" />
      {/* legend */}
      <g fontFamily="monospace" fontSize="11">
        <line x1="120" y1="386" x2="150" y2="386" stroke={INK} strokeOpacity="0.55" strokeWidth="2" />
        <text x="158" y="390" fill={INK}>happy path</text>
        <line x1="270" y1="386" x2="300" y2="386" stroke={BLUE} strokeWidth="1.8" strokeDasharray="5 5" />
        <text x="308" y="390" fill={BLUE}>alternative path</text>
        <line x1="460" y1="386" x2="490" y2="386" stroke={ORANGE} strokeWidth="1.8" strokeDasharray="5 5" />
        <text x="498" y="390" fill={ORANGE}>error + recovery</text>
      </g>
    </Canvas>
  );
}

