/* Five phone screens across a mobile shopping journey. */
function MobileJourney() {
  const screens: { label: string[]; blocks: Block[] }[] = [
    {
      label: ["Menu +", "search"],
      blocks: [
        { x: 10, y: 26, w: 96, h: 20, label: "Search", size: 9, blue: true, left: true },
        ...[0, 1, 2, 3, 4].map((i) => ({ x: 10, y: 56 + i * 26, w: 96, h: 20, tone: "soft" as BlockTone, label: i === 0 ? "Category ›" : "", size: 9, left: true })),
      ],
    },
    {
      label: ["Listing +", "filters"],
      blocks: [
        { x: 10, y: 26, w: 46, h: 18, label: "Filter", size: 8.5, hot: true },
        { x: 60, y: 26, w: 46, h: 18, label: "Sort", size: 8.5 },
        ...[0, 1].flatMap((r) => [0, 1].map((c) => ({ x: 10 + c * 50, y: 52 + r * 72, w: 46, h: 64, tone: "soft" as BlockTone }))),
      ],
    },
    {
      label: ["Product"],
      blocks: [
        { x: 10, y: 26, w: 96, h: 84, label: "Swipe gallery", size: 8.5, tone: "soft" },
        { x: 10, y: 118, w: 70, h: 10, tone: "ink" },
        { x: 10, y: 134, w: 96, h: 18, label: "S  M  L  XL", size: 8.5, left: true },
        { x: 6, y: 186, w: 104, h: 24, label: "Add to cart", size: 9, tone: "ink" },
      ],
    },
    {
      label: ["Cart"],
      blocks: [
        ...[0, 1].map((i) => ({ x: 10, y: 26 + i * 44, w: 96, h: 38, label: "Item · qty ± ", size: 8.5, left: true })),
        { x: 10, y: 120, w: 96, h: 34, label: "Total incl.|delivery", size: 8.5, blue: true },
        { x: 6, y: 186, w: 104, h: 24, label: "Checkout", size: 9, tone: "ink" },
      ],
    },
    {
      label: ["Checkout"],
      blocks: [
        { x: 10, y: 26, w: 96, h: 22, label: "Express pay", size: 8.5, hot: true },
        ...[0, 1, 2].map((i) => ({ x: 10, y: 58 + i * 28, w: 96, h: 22, tone: "white" as BlockTone, label: i === 0 ? "Email" : i === 1 ? "Address" : "Card", size: 8.5, left: true })),
        { x: 6, y: 186, w: 104, h: 24, label: "Pay now", size: 9, tone: "ink" },
      ],
    },
  ];
  const w = 116;
  const h = 222;
  const y = 90;
  return (
    <Canvas>
      {screens.map((s, i) => {
        const x = 44 + i * 148;
        return (
          <g key={i}>
            <rect x={x} y={y} width={w} height={h} rx="16" fill="#ffffff" stroke={INK} strokeWidth="2" />
            <rect x={x + w / 2 - 14} y={y + 8} width="28" height="4" rx="2" fill={INK} opacity="0.8" />
            {s.blocks.map((b, j) => (
              <BlockShape key={j} b={{ ...b, x: x + b.x, y: y + b.y }} />
            ))}
            {s.label.map((l, j) => (
              <text key={l} x={x + w / 2} y={y + h + 28 + j * 15} textAnchor="middle" fontFamily="monospace" fontSize="11" fill={INK}>
                {l}
              </text>
            ))}
            {i < screens.length - 1 && (
              <g>
                <line x1={x + w + 6} y1={y + h / 2} x2={x + w + 26} y2={y + h / 2} stroke={LINE} strokeWidth="2" />
                <path d={arrow(x + w + 26, y + h / 2, "r")} stroke={LINE} strokeWidth="2" fill="none" />
              </g>
            )}
          </g>
        );
      })}
      <text x="400" y="408" textAnchor="middle" fontFamily="monospace" fontSize="11" fill={BLUE}>
        thumb-reachable actions · sticky primary button · no dead ends
      </text>
    </Canvas>
  );
}

function Canvas({ children }: { children: React.ReactNode }) {
  return (
    <svg
      viewBox="0 0 800 450"
      preserveAspectRatio="xMidYMid slice"
      className="h-full w-full"
      aria-hidden="true"
    >
      <rect x="0" y="0" width="800" height="450" fill="#faf9f6" />
      {children}
    </svg>
  );
}

