    return (
      <Canvas>
        <line x1="150" y1="70" x2="150" y2="380" stroke={LINE} strokeWidth="2" />
        {bars.map((b, i) => (
          <g key={i}>
            <rect x="150" y={90 + i * 48} width={b.w} height="22" rx="4" fill={b.c} opacity={b.c === LINE ? 0.8 : 1} />
          </g>
        ))}
      </Canvas>
    );
